import requests, re, urllib.parse, html
queries = [
    'site:bloomingbit.io "Bitcoin Briefly Falls Below $77,000 as $500 Million in Longs Liquidated in an Hour"',
    'site:finance.yahoo.com "Crypto Long Liquidations Hit $584 Million in 24-Hour Sell-Off"',
    'site:thedeepdive.ca "Crypto Market Takes Another Hit as Bitcoin Dips Below $77K in Monday Flash Crash"',
    'site:startupfortune.com "Bitcoin Slides Under $77,000 as Macro Storm Hits Crypto"',
    'site:bitbo.io "Bitcoin Drops Below $77K on Trump\'s Iran Warning"',
    'site:grafa.com "Crypto long liquidations reach $584M amid market drop"',
]
headers={'User-Agent':'Mozilla/5.0'}
for q in queries:
    url='https://html.duckduckgo.com/html/?q='+urllib.parse.quote(q)
    print('\nQUERY:', q)
    try:
        html_text=requests.get(url,headers=headers,timeout=20).text
        # print first 500 chars for inspection
        # parse uddg params
        found=[]
        for m in re.finditer(r'nofollow" class="[^"]*result__a" href="(.*?)"', html_text):
            u=html.unescape(m.group(1))
            if 'uddg=' in u:
                u=urllib.parse.parse_qs(urllib.parse.urlparse(u).query).get('uddg',[u])[0]
            found.append(u)
        if not found:
            for m in re.finditer(r'<a rel="nofollow" href="(.*?)">', html_text):
                u=html.unescape(m.group(1))
                if 'uddg=' in u:
                    u=urllib.parse.parse_qs(urllib.parse.urlparse(u).query).get('uddg',[u])[0]
                if u.startswith('http'):
                    found.append(u)
        for u in found[:10]:
            print(u)
        if not found:
            print('NO_LINKS')
            print(html_text[:1000])
    except Exception as e:
        print('ERR',e)
PY
